function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*104729+7);var total=120,every=10+((R()*15)|0),crashAt=20+((R()*90)|0);var ckpts=0,lastCk=0;for(var op=1;op<=crashAt;op++){if(op%every===0){ckpts++;lastCk=op;}}var redone=crashAt-lastCk;return{ops_total:total,checkpoint_every:every,checkpoints_taken:ckpts,crashed_at_op:crashAt,resumed_from_op:lastCk,ops_redone:redone,recovery_cost_pct:+(100*redone/total).toFixed(1)};}
var SEED = 77501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

